INSERT INTO "Lab" ("id", "name", "slug", "description", "createdAt", "updatedAt") VALUES ('c211f80d-bba0-4d2b-9004-5958c731a6b6', 'ModSecurity WAF', 'modsecurity-waf', 'Web Application Firewall with ModSecurity and Nginx', NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('469f6aa9-4a5b-47d6-acf7-cefb3b62bc75', 'c211f80d-bba0-4d2b-9004-5958c731a6b6', 1, 'Install modsecurity-nginx connector: apt install libmodsecurity-dev. Run: nginx -V 2>&1 | grep -o modsecurity. What module name is shown?', 'apt install libmodsecurity-dev && nginx -V 2>&1 | grep -o modsecurity', '$2b$10$VBzwbAg8oheRlBF7OskUo.9NjQMeu2IkbdGYfWmvTwmC5V8WY55qK', 'MODSECURITY_INSTALLED', 10, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('3d00a413-2966-4a40-89cd-2c00ca99ae10', 'c211f80d-bba0-4d2b-9004-5958c731a6b6', 2, 'Enable OWASP Core Rule Set: clone the CRS repo into /etc/nginx/modsecurity/. Run: ls /etc/nginx/modsecurity/owasp-crs/rules/ | head -5. How many rule files are listed?', 'git clone https://github.com/coreruleset/coreruleset /etc/nginx/modsecurity/owasp-crs && ls /etc/nginx/modsecurity/owasp-crs/rules/ | head -5', '$2b$10$rEM0Cyz6A1Bh1NocGWZNNOQXXmSGdoR/xWbrc.uiwkCy7VXW9uc3W', 'OWASP_CRS_ENABLED', 20, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('5c268224-efe2-4863-8ec5-159e7fbe6962', 'c211f80d-bba0-4d2b-9004-5958c731a6b6', 3, 'Test SQL injection detection: curl -s -o /dev/null -w "%{http_code}" "http://localhost/?id=1%27%20OR%201=1--". What HTTP status code is returned?', 'curl -s -o /dev/null -w "%{http_code}" "http://localhost/?id=1%27%20OR%201=1--"', '$2b$10$n5KZ6f9lnCGPseHkLOORS.pAJgO1V8nPuJpp67krnmorug.5uLNii', 'SQLI_DETECTED', 30, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
