INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('275715c5-d835-4f45-b1fa-a8c6f1cc6200', 'c211f80d-bba0-4d2b-9004-5958c731a6b6', 5, 'View ModSecurity audit logs: tail -30 /var/log/modsec_audit.log. What event IDs are visible in the log output?', 'tail -30 /var/log/modsec_audit.log', '$2b$10$U.HCQ10fjDs4NRg0ndsPGu3MwVC0qh5K3Yj4nla9nDKI8Uex9moAy', 'AUDIT_LOGS_VIEWED', 50, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('2ac1f845-d35b-4c61-bef5-b8f97c575b1f', 'c211f80d-bba0-4d2b-9004-5958c731a6b6', 6, 'Configure a custom rule to block the /admin path: add SecRule REQUEST_URI to deny requests beginning with /admin in modsecurity.conf. Run: nginx -t. What output does the config test produce?', 'Add SecRule REQUEST_URI deny /admin in modsecurity.conf and run nginx -t', '$2b$10$FzJYgp43oOzHMbeprVHFB.ikhZzZANL85wJZW1RrrcnRMG/sFat2e', 'CUSTOM_RULE_CONFIGURED', 60, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
