INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('26d2f224-277b-4b30-a66e-89275f7a6eac', 'c211f80d-bba0-4d2b-9004-5958c731a6b6', 9, 'Configure paranoia level: set SecRuleEngine On and SecPcreMatchLimit 100000 in modsecurity.conf. Run: nginx -t && curl -s -o /dev/null -w "%{http_code}" http://localhost/. What status code is returned?', 'Set SecRuleEngine On and SecPcreMatchLimit 100000 then run nginx -t', '$2b$10$3QxHyC6QmgIZg.GInzokYOwDtQlpU6qjkexxXMCDbCxSL/WT7Lhga', 'PARANOIA_LEVEL_CONFIGURED', 90, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
